// Only care about agents/council-*.md files touched by this PR
const files = $input.first().json;
const arr = Array.isArray(files) ? files : (files.data || []);
const targets = arr.filter(f => /^agents\/council-.*\.md$/.test(f.filename));
if (targets.length === 0) return [{ json: { skip: true } }];
return targets.map(f => ({ json: { filename: f.filename, raw_url: f.raw_url } }));

// Enforce council conventions from CLAUDE.md
const body = $input.first().json.data || $input.first().json.body || '';
const fn = $('Filter Agent Files').item.json.filename;
const order = ['## Identity', '## Grounding Protocol', '## Analytical Method', '## What You See', '## What You Miss', '## When Deliberating', '## Output Format'];
const issues = [];
if (!body.startsWith('---')) issues.push('Missing YAML frontmatter');
const positions = order.map(h => ({ h, i: body.indexOf(h) }));
for (const p of positions) if (p.i === -1) issues.push('Missing section: ' + p.h);
const present = positions.filter(p => p.i !== -1);
for (let i = 1; i < present.length; i++) if (present[i].i < present[i-1].i) issues.push('Out-of-order section: ' + present[i].h);
if (body.indexOf('## Grounding Protocol') > body.indexOf('## Analytical Method') && body.indexOf('## Analytical Method') !== -1) issues.push('Grounding Protocol must come immediately after Identity');
return [{ json: { filename: fn, ok: issues.length === 0, issues } }];

